import{XO_CONFIG as c}from"./config.min.js";export const KINDS=Object.freeze(["fifty","pick","catch","sack","tackle","release"]);export function ballEvent(t,e){return!t||!e||!e.thrown||!e.holder||e.holder===t.holder||t.holder&&t.thrown?null:{kind:e.team===0?"catch":"pick",hero:e.holder,partner:null}}export function tackleKind({carrier:t,threw:e,ran:o}){return t==="qb"&&!e&&!o?"sack":"tackle"}export function delayFor(t){const e=c.moments.after[t];return Number.isFinite(e)&&e>0?e:0}export function involves(t,e){return!!e&&(t.hero===e||t.partner===e)}export function rankMoments(t,e=null,o=c.moments.keep){const a=t.some(r=>r.kind!=="release"),l=t.filter(r=>r.kind!=="release"||!a||involves(r,e)),i=r=>r.kind==="release"?2:involves(r,e)?0:1;return l.map((r,n)=>({m:r,i:n})).sort((r,n)=>i(r.m)-i(n.m)||KINDS.indexOf(r.m.kind)-KINDS.indexOf(n.m.kind)||(r.m.at||0)-(n.m.at||0)||r.i-n.i).slice(0,Math.max(0,o)).map(({m:r})=>r)}export const KIND_NAMES=Object.freeze({fifty:"Fifty",pick:"Interception",catch:"Catch",sack:"Sack",tackle:"Tackle",release:"Throw"});export function previewShot(t){const e=c.moments.preview,o=t.z>=0?-1:1;return{position:{x:t.x,y:e.height,z:t.z+o*e.distance},target:{x:t.x,y:e.aimY,z:t.z},fov:e.fov}}
